-- The brand email reframed (Sean, 2026-11-19: the World Vegan Expo ladder, signed by Sean: "I'm fine with you putting me signing it").
-- The first ask is claiming the brand's listing; the link is /expo?b={slug}, whose Claim button opens their own listing. Still a DRAFT
-- until Sean approves it in HQ Outreach.
update ve_outreach_campaigns set name = 'Brands: claim your page, on the road to the World Vegan Expo', link_path = '/expo?b={slug}' where slug='giving-2026-brands' and status='draft';
update ve_outreach_campaign_emails set subject = '{business}, your page on Vegans Explore is ready to claim',
 body = E'Hi {first_name},\n\nI''m Sean Russell, founder of Vegans Explore. For ten years I ran Vegan events in South and Central Florida: potlucks, festivals and expos. Now we''re building that community city by city, and {business} already has a page in our Directory.\n\nThe first step is to claim it. It''s free, it takes about a minute, and you control your logo, your words and your links before we open on January 1.\n\nFrom there, every step is your choice: a Spotlight day for our members, with your product as the prize and your code for everyone who enters; our first community nights with local Vegan clubs in South Florida, Central Florida and Philadelphia this winter; and, down the road, the World Vegan Expo in early 2028.\n\nIt''s all on one page, with your listing one click away:\n{link}\n\nIf you have a question, just reply to this email.\n\nSean A. Russell\nFounder, Vegans Explore', updated_at = now()
 where campaign_slug='giving-2026-brands' and step=1;
-- canon-ve-community-managers v4: eligible to be considered at Level 3.
update knowledge_records set body = body || jsonb_build_object('eligibility_level_v4','A member becomes eligible to be considered for Community Manager at Level 3 (Sean, 2026-11-19: "Let''s say level 3, they can be eligible").'), version = 4, change_summary = 'v4 (Sean, 2026-11-19): eligible to be considered for Community Manager at Level 3.', updated_by='Logan Russell', updated_at=now() where slug='canon-ve-community-managers';
